// Turns code back into a builder design.
// 1. Exact: code generated by the builder carries its state in a comment (heigin-builder:v1:...).
// 2. Best effort: hand-written TSX using @heigin/ui is parsed with @babel/parser (loaded lazily) and
//    mapped element-by-element to blocks; anything unrecognised is reported, not guessed.
import type * as T from "@babel/types";
import { createNode } from "./blocks";
import { STATE_PREFIX, decodeDoc } from "./codegen";
import { ICONS } from "./data";
import { node, type BuilderDoc, type BuilderNode, type PropValue } from "./model";
import { isValidDoc } from "./storage";

export interface ImportResult {
  doc: BuilderDoc;
  exact: boolean;
  warnings: string[];
}

export async function importCode(source: string): Promise<ImportResult> {
  const marker = new RegExp(`${STATE_PREFIX}([A-Za-z0-9_-]+)`).exec(source);
  if (marker) {
    try {
      const doc = decodeDoc(marker[1]!);
      if (isValidDoc(doc)) return { doc, exact: true, warnings: [] };
    } catch {
      // fall through to parsing
    }
  }
  const { parse } = await import("@babel/parser");
  const ast = parse(source, { sourceType: "module", plugins: ["jsx", "typescript"], errorRecovery: true });
  const warnings: string[] = [];
  const name = componentName(ast) ?? "ImportedPage";
  const jsx = findRootJsx(ast);
  if (!jsx) throw new Error("No JSX found. Paste a React component that returns JSX.");
  const top = convertRoot(jsx, warnings);
  return { doc: { ...top, name }, exact: false, warnings: [...new Set(warnings)] };
}

// ───────────── AST helpers
type JsxNode = T.JSXElement | T.JSXFragment;

function walk(n: unknown, visit: (n: T.Node) => boolean | void) {
  if (!n || typeof n !== "object") return;
  const node = n as T.Node;
  if (typeof node.type === "string" && visit(node) === false) return;
  for (const key of Object.keys(node)) {
    if (key === "loc" || key === "start" || key === "end" || key === "leadingComments" || key === "trailingComments") continue;
    const v = (node as unknown as Record<string, unknown>)[key];
    if (Array.isArray(v)) v.forEach((c) => walk(c, visit));
    else if (v && typeof v === "object") walk(v, visit);
  }
}

function componentName(ast: T.File): string | null {
  let name: string | null = null;
  walk(ast.program, (n) => {
    if (n.type === "ExportDefaultDeclaration" && n.declaration.type === "FunctionDeclaration" && n.declaration.id) {
      name = n.declaration.id.name;
      return false;
    }
  });
  return name;
}

/** The JSX returned by the default export (or the first top-level JSX in the file). */
function findRootJsx(ast: T.File): JsxNode | null {
  let found: JsxNode | null = null;
  const scan = (root: unknown) =>
    walk(root, (n) => {
      if (found) return false;
      if (n.type === "ReturnStatement" && n.argument && (n.argument.type === "JSXElement" || n.argument.type === "JSXFragment")) {
        found = n.argument;
        return false;
      }
      if (n.type === "JSXElement" || n.type === "JSXFragment") {
        found = n;
        return false;
      }
    });
  walk(ast.program, (n) => {
    if (n.type === "ExportDefaultDeclaration") {
      scan(n.declaration);
      return false;
    }
  });
  if (!found) scan(ast.program);
  return found;
}

const tagName = (el: T.JSXElement) => {
  const n = el.openingElement.name;
  return n.type === "JSXIdentifier" ? n.name : n.type === "JSXMemberExpression" ? `${(n.object as T.JSXIdentifier).name}.${n.property.name}` : "";
};

/** Evaluates literal expressions (strings, numbers, booleans, arrays/objects of literals). */
function evalLiteral(e: T.Node | null | undefined): unknown {
  if (!e) return undefined;
  switch (e.type) {
    case "StringLiteral":
    case "NumericLiteral":
    case "BooleanLiteral":
      return e.value;
    case "TemplateLiteral":
      return e.expressions.length ? undefined : e.quasis.map((q) => q.value.cooked).join("");
    case "ArrayExpression":
      return e.elements.map((x) => evalLiteral(x));
    case "ObjectExpression":
      return Object.fromEntries(
        e.properties
          .filter((p): p is T.ObjectProperty => p.type === "ObjectProperty")
          .map((p) => [p.key.type === "Identifier" ? p.key.name : p.key.type === "StringLiteral" ? p.key.value : "?", evalLiteral(p.value)]),
      );
    case "TSAsExpression":
    case "TSSatisfiesExpression":
      return evalLiteral(e.expression);
    case "UnaryExpression":
      return e.operator === "-" && e.argument.type === "NumericLiteral" ? -e.argument.value : undefined;
    default:
      return undefined;
  }
}

function attrs(el: T.JSXElement): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const a of el.openingElement.attributes) {
    if (a.type !== "JSXAttribute" || a.name.type !== "JSXIdentifier") continue;
    const k = a.name.name;
    if (!a.value) out[k] = true;
    else if (a.value.type === "StringLiteral") out[k] = a.value.value;
    else if (a.value.type === "JSXExpressionContainer") {
      const ex = a.value.expression;
      out[k] = ex.type === "JSXElement" || ex.type === "JSXFragment" ? ex : evalLiteral(ex as T.Node);
    }
  }
  return out;
}

const elementChildren = (el: JsxNode): T.JSXElement[] =>
  el.children.flatMap((c) =>
    c.type === "JSXElement" ? [c] : c.type === "JSXFragment" ? elementChildren(c) : c.type === "JSXExpressionContainer" && c.expression.type === "JSXElement" ? [c.expression] : [],
  );

function textOf(el: JsxNode): string {
  return el.children
    .map((c) =>
      c.type === "JSXText"
        ? c.value
        : c.type === "JSXExpressionContainer" && c.expression.type !== "JSXEmptyExpression"
          ? String(evalLiteral(c.expression) ?? "")
          : c.type === "JSXElement"
            ? textOf(c)
            : "",
    )
    .join("")
    .replace(/\s+/g, " ")
    .trim();
}

/** Lucide icon name of an element like <Plus strokeWidth={1.6} /> (if known). */
function iconName(v: unknown): string {
  if (v && typeof v === "object" && (v as T.Node).type === "JSXElement") {
    const n = tagName(v as T.JSXElement);
    return ICONS[n] ? n : "none";
  }
  return "none";
}

const str = (v: unknown) => (typeof v === "string" ? v : typeof v === "number" ? String(v) : "");
const bool = (v: unknown) => v === true;

/** Block with defaults, overridden by the given (defined) props. */
function block(type: string, props: Record<string, PropValue | undefined>, children?: BuilderNode[]): BuilderNode {
  const n = createNode(type);
  const clean = Object.fromEntries(Object.entries(props).filter(([, v]) => v !== undefined)) as Record<string, PropValue>;
  return { ...n, props: { ...n.props, ...clean }, children: children ?? [] };
}

function styleOf(a: Record<string, unknown>): Record<string, unknown> {
  return a.style && typeof a.style === "object" && !("type" in (a.style as object)) ? (a.style as Record<string, unknown>) : {};
}

// ───────────── element → blocks
function convertRoot(el: JsxNode, warnings: string[]): Omit<BuilderDoc, "name"> {
  if (el.type === "JSXElement") {
    const a = attrs(el);
    const st = styleOf(a);
    const tag = tagName(el);
    if (tag === "div" && st.maxWidth) return { mode: "page", root: node("page", {}, convertChildren(el, warnings)) };
    if (tag === "section") {
      const [n] = convert(el, warnings);
      if (n) return { mode: "section", root: n };
    }
  }
  const kids = el.type === "JSXFragment" ? convertChildren(el, warnings) : convert(el, warnings);
  return { mode: "component", root: node("fragment", {}, kids) };
}

function convertChildren(el: JsxNode, warnings: string[]): BuilderNode[] {
  return elementChildren(el).flatMap((c) => convert(c, warnings));
}

function convert(el: T.JSXElement, warnings: string[]): BuilderNode[] {
  const tag = tagName(el);
  const a = attrs(el);
  const st = styleOf(a);
  const kids = () => convertChildren(el, warnings);
  const actionsFrom = (v: unknown) => (v && typeof v === "object" && "type" in (v as object) ? convertChildren(fakeWrap(v as JsxNode), warnings) : []);

  switch (tag) {
    case "div":
    case "main": {
      if (st.display === "grid" && typeof st.gridTemplateColumns === "string") {
        const cols = /repeat\((\d+)/.exec(st.gridTemplateColumns);
        const min = /minmax\((\d+)px/.exec(st.gridTemplateColumns);
        return [block("grid", { columns: cols ? Number(cols[1]) : 2, responsive: !cols, minWidth: min ? Number(min[1]) : undefined }, kids())];
      }
      if (st.display === "flex") return [block("stack", { direction: st.flexDirection === "row" || !st.flexDirection ? "row" : "column" }, kids())];
      return [block("stack", { direction: "column" }, kids())];
    }
    case "section": {
      const children = elementChildren(el);
      const first = children[0];
      const title = first && tagName(first) === "h2" ? textOf(first) : "";
      const rest = title ? children.slice(1) : children;
      return [block("section", { title }, rest.flatMap((c) => convert(c, warnings)))];
    }
    case "h1":
      return [block("text", { variant: "title", text: textOf(el) })];
    case "h2":
      return [block("text", { variant: "heading", text: textOf(el) })];
    case "h3":
      return [block("text", { variant: "label", text: textOf(el) })];
    case "p":
      return [block("text", { variant: typeof st.color === "string" && st.color.includes("muted") ? "muted" : "body", text: textOf(el) })];
    case "hr":
      return [block("divider", {})];
    case "form": {
      const buttons = findAll(el, "Button");
      const submit = buttons.find((b) => attrs(b).type === "submit");
      const cancel = buttons.find((b) => attrs(b).type === "reset");
      const fields = elementChildren(el).filter((c) => !(tagName(c) === "div" && findAll(c, "Button").length));
      return [block("form", { submitLabel: submit ? textOf(submit) : undefined, cancelLabel: cancel ? textOf(cancel) : "" }, fields.flatMap((c) => convert(c, warnings)))];
    }
    case "ul": {
      const items = elementChildren(el).filter((c) => tagName(c) === "ConversationListItem");
      if (items.length)
        return [
          block("conversationList", {
            items: items.map((i) => { const x = attrs(i); return [str(x.name), str(x.preview), str(x.channel) || "whatsapp", str(x.timeLabel), str(x.unreadCount) || "0"].join(" | "); }).join("\n"),
          }),
        ];
      if (findAll(el, "TaskRow").length) return [block("taskList", {})];
      return kids();
    }
    case "Card": {
      const header = elementChildren(el).find((c) => tagName(c) === "CardHeader");
      const h = header ? attrs(header) : {};
      return [
        block(
          "card",
          { title: str(h.title), description: str(h.description), padding: str(a.padding) || "md" },
          elementChildren(el).filter((c) => c !== header).flatMap((c) => convert(c, warnings)),
        ),
      ];
    }
    case "PageHeader":
      return [block("pageHeader", { title: str(a.title), description: str(a.description) }, actionsFrom(a.actions))];
    case "Button": {
      const icon = iconName(a.leadingIcon ?? a.trailingIcon);
      return [
        block("button", {
          label: textOf(el),
          variant: str(a.variant) || "primary",
          size: str(a.size) || "md",
          icon,
          iconPosition: a.trailingIcon ? "trailing" : "leading",
          disabled: bool(a.disabled),
          fullWidth: bool(a.fullWidth),
        }),
      ];
    }
    case "IconButton":
      return [block("iconButton", { label: str(a.label), icon: iconName(a.icon) === "none" ? "Pencil" : iconName(a.icon), variant: str(a.variant) || "ghost", size: str(a.size) || "md" })];
    case "Badge":
      return [block("badge", { label: textOf(el), tone: str(a.tone) || "neutral", dot: bool(a.dot) })];
    case "StatusBadge":
      return [block("statusBadge", { status: str(a.status) || undefined })];
    case "Avatar":
      return [block("avatar", { name: str(a.name), size: str(a.size) || "md" })];
    case "Field": {
      const control = elementChildren(el)[0];
      const c = control ? attrs(control) : {};
      const ct = control ? tagName(control) : "";
      const common = { label: str(a.label), required: bool(a.required), name: str(c.name) };
      if (ct === "Textarea") return [block("textarea", { ...common, placeholder: str(c.placeholder), rows: typeof c.rows === "number" ? c.rows : undefined })];
      if (ct === "NativeSelect") {
        const opts = elementChildren(control!).filter((o) => tagName(o) === "option");
        const placeholder = opts.find((o) => attrs(o).value === "");
        return [block("select", { ...common, placeholder: placeholder ? textOf(placeholder) : "", options: opts.filter((o) => o !== placeholder).map(textOf).join("\n") })];
      }
      if (ct === "Select") {
        return [block("select", { ...common, placeholder: str(c.placeholder), options: Array.isArray(c.options) ? (c.options as { label?: string }[]).map((o) => str(o?.label)).join("\n") : "" })];
      }
      return [block("input", { ...common, description: str(a.description), placeholder: str(c.placeholder), type: str(c.type) || "text" })];
    }
    case "Checkbox":
    case "Switch":
      return [block(tag === "Checkbox" ? "checkbox" : "switch", { label: str(a.label), description: str(a.description), defaultChecked: bool(a.defaultChecked), name: str(a.name) })];
    case "RadioGroup": {
      const opts = Array.isArray(a.options) ? (a.options as { label?: string }[]).map((o) => str(o?.label)).join("\n") : undefined;
      return [block("radioGroup", { label: str(a.label), options: opts, orientation: str(a.orientation) || "vertical", name: str(a.name) })];
    }
    case "Tabs": {
      const list = findAll(el, "TabsList")[0];
      return [block("tabs", { tabs: findAll(el, "Tab").map(textOf).join("\n"), variant: list ? str(attrs(list).variant) || "pill" : "pill" })];
    }
    case "MetricGroup":
      return [block("metricGroup", { label: str(a.label), columns: typeof a.columns === "number" ? a.columns : undefined }, kids())];
    case "MetricCard":
      return [block("metric", { label: str(a.label), value: str(a.value), hint: str(a.hint), icon: iconName(a.icon), tone: str(a.tone) || "default" })];
    case "Table":
      warnings.push("Table imported with the sample Leads columns — reconnect your columns and rows after copying.");
      return [block("table", { caption: str(a.caption) || "Leads", selectable: "selectedIds" in a, loading: undefined })];
    case "FilterToolbar":
      return [block("filterToolbar", { placeholder: str(a.searchPlaceholder) || str(a.searchLabel), scope: str(a.scope), chips: a.chips ? findAll(fakeWrap(a.chips as JsxNode), "FilterChip").map(textOf).join("\n") : "" })];
    case "ApprovalCard":
      return [block("approvalCard", { title: str(a.title), reason: str(a.reason), requestedBy: str(a.requestedBy), approveLabel: str(a.approveLabel) || "Approve", undoable: a.undoable !== false })];
    case "ActivityTimeline":
      return [block("activityTimeline", { items: findAll(el, "ActivityItem").map((i) => `${textOf(i)} | ${str(attrs(i).timeLabel)}`).join("\n") })];
    case "DetailList":
      return [block("detailList", { items: Array.isArray(a.items) ? (a.items as { label?: string; value?: string }[]).map((i) => `${str(i?.label)}: ${str(i?.value)}`).join("\n") : undefined })];
    case "DealStage":
      return [block("dealStage", { stages: Array.isArray(a.stages) ? (a.stages as string[]).join("\n") : undefined, current: str(a.current), lost: bool(a.lost), compact: bool(a.compact) })];
    case "EmptyState": {
      const action = a.action && typeof a.action === "object" ? textOf(a.action as JsxNode) : "";
      if (iconName(a.icon) === "none" && a.icon && tagName(a.icon as T.JSXElement) === "TriangleAlert")
        return [block("errorState", { title: str(a.title), description: str(a.description), retryLabel: action })];
      return [block("emptyState", { title: str(a.title), description: str(a.description), actionLabel: action })];
    }
    case "Dialog":
    case "Drawer": {
      const trigger = findAll(el, `${tag}Trigger`)[0];
      const content = findAll(el, `${tag}Content`)[0];
      const c = content ? attrs(content) : {};
      return [
        block(
          tag === "Dialog" ? "dialog" : "drawer",
          { triggerLabel: trigger ? textOf(trigger) : "Open", title: str(c.title), description: str(c.description), side: str(c.side) || undefined },
          content ? convertChildren(content, warnings).flatMap((n) => (n.type === "stack" ? n.children : [n])) : [],
        ),
      ];
    }
    case "DropdownMenu": {
      const trigger = findAll(el, "DropdownMenuTrigger")[0];
      const items = findAll(el, "DropdownMenuItem").map((i) => (attrs(i).tone === "danger" ? `!${textOf(i)}` : textOf(i)));
      return [block("dropdownMenu", { triggerLabel: trigger ? textOf(trigger) : "Actions", items: items.join("\n") })];
    }
    case "SidebarNav":
    case "aside":
      warnings.push("Sidebar navigation is only supported via the App layout template.");
      return [];
    default: {
      const children = kids();
      warnings.push(children.length ? `<${tag}> isn't a builder block — kept its children.` : `<${tag}> isn't a builder block — skipped.`);
      return children;
    }
  }
}

/** All descendant elements with the given tag (depth-first). */
function findAll(el: JsxNode, tag: string): T.JSXElement[] {
  const out: T.JSXElement[] = [];
  walk(el, (n) => {
    if (n.type === "JSXElement" && tagName(n) === tag) out.push(n);
  });
  return out;
}

/** Treats a JSX attribute value (element or fragment) as a container for conversion. */
function fakeWrap(v: JsxNode): JsxNode {
  return v.type === "JSXFragment" ? v : ({ type: "JSXFragment", children: [v] } as unknown as T.JSXFragment);
}
